    Node* removed = head->next;
    head->next = removed->next;
    delete removed;
    inspect("middle deleted", head);
    removeHead(head);
    inspect("head deleted", head);
    removeHead(head);
    inspect("only node deleted", head);
    removeHead(head);
    inspect("empty case safe", head);
    printList(head);
}

